// Window = since the last production run (max 96 h back) until now.
const cfg = $('Config').first().json;
const sd = $getWorkflowStaticData('global');
const now = Date.now();
let since = sd.lastRun ? Date.parse(sd.lastRun) : now - cfg.default_lookback_hours * 3600e3;
since = Math.max(since, now - cfg.max_lookback_hours * 3600e3);
return cfg.channels.map(c => ({ json: { channel: c.id, channel_name: c.name, oldest: String(Math.floor(since / 1000)), since: new Date(since).toISOString(), until: new Date(now).toISOString() } }));

// One request per thread that has replies (parents inside the window).
const chans = $('Compute Window').all();
const out = [];
$input.all().forEach((it, i) => {
  const ch = chans[i] && chans[i].json;
  for (const m of (it.json.messages || [])) if (m.reply_count > 0 && ch) out.push({ json: { channel: ch.channel, ts: m.thread_ts || m.ts } });
});
return out.slice(0, 80);

// Joins channel messages + thread replies into one compact digest for Nova.
const cfg = $('Config').first().json;
const chans = $('Compute Window').all().map(i => i.json);
const hist = $('Slack · Channel History').all();
const reqs = $('Thread Requests').all().map(i => i.json);
const reps = $('Slack · Thread Replies').all();
const link = (ch, ts) => `https://${cfg.slack_workspace}.slack.com/archives/${ch}/p${String(ts).replace('.', '')}`;
const clean = (t) => String(t || '').replace(/<(https?:[^|>]+)\|([^>]+)>/g, '$2').replace(/<(https?:[^>]+)>/g, '$1').replace(/\s+/g, ' ').trim();
const keep = (m) => m && m.type === 'message' && !['channel_join', 'channel_leave', 'channel_topic', 'channel_purpose', 'bot_add'].includes(m.subtype) && clean(m.text).length >= 15;

const errors = [];
const blocks = [];
let total = 0;
chans.forEach((ch, i) => {
  const h = hist[i] ? hist[i].json : {};
  if (h.ok === false || h.error) { errors.push(`${ch.channel_name}: ${h.error || (h.error && h.error.message) || 'error'}`); return; }
  const threads = {};
  reqs.forEach((r, k) => { if (r.channel === ch.channel && reps[k]) threads[r.ts] = (reps[k].json.messages || []).filter(m => m.ts !== r.ts && keep(m)); });
  const msgs = (h.messages || []).filter(keep).sort((a, b) => a.ts - b.ts);
  if (!msgs.length) return;
  const lines = [`## #${ch.channel_name}`];
  for (const m of msgs) {
    total++;
    lines.push(`- [${new Date(m.ts * 1000).toISOString().slice(0, 16)}] (${link(ch.channel, m.ts)}) ${clean(m.text).slice(0, 1500)}`);
    for (const r of (threads[m.thread_ts || m.ts] || []).slice(0, 25)) { total++; lines.push(`    ↳ ${clean(r.text).slice(0, 800)}`); }
  }
  blocks.push(lines.join('\n'));
});
let digest = blocks.join('\n\n');
const cut = digest.length > cfg.max_digest_chars;
if (cut) digest = digest.slice(-cfg.max_digest_chars);
return [{ json: { digest, messages: total, channels_with_activity: blocks.length, slack_errors: errors, digest_cut: cut, since: chans[0] && chans[0].since, until: chans[0] && chans[0].until } }];

