// Help Center searches for each change: up to 3 keywords per language, in es-419 and en-us.
const cfg = $('Config').first().json;
const changes = (($json.output || {}).changes || []).slice(0, cfg.max_changes);
const uniq = (a) => [...new Set((a || []).map(k => String(k).trim()).filter(Boolean))].slice(0, 3);
const out = [];
for (const c of changes) {
  const es = uniq(c.keywords_es), en = uniq(c.keywords_en);
  for (const q of es) out.push({ json: { change_id: c.id, query: q, locale: 'es-419' } });
  for (const q of en) out.push({ json: { change_id: c.id, query: q, locale: 'en-us' } });
}
return out.slice(0, 90);

// Candidate articles per change, with the relevant passages (around the change's keywords) instead of full bodies.
const changes = (($('Nova · Extract Changes').first().json.output || {}).changes || []);
const reqs = $('Search Requests').all().map(i => i.json);
const res = $input.all().map(i => i.json);
const strip = (h) => String(h || '').replace(/<(br|\/p|\/li|\/h\d|\/tr)[^>]*>/gi, '\n').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim();
const byChange = {};
reqs.forEach((r, i) => {
  if (!r.change_id) return;
  for (const a of ((res[i] || {}).results || [])) {
    const key = a.id + '|' + a.locale;
    (byChange[r.change_id] ||= {})[key] ||= a;
  }
});
const passages = (text, terms) => {
  const lower = text.toLowerCase(), spans = [];
  for (const t of terms) {
    let from = 0, n = 0, idx;
    while ((idx = lower.indexOf(t, from)) !== -1 && n < 3) { spans.push([Math.max(0, idx - 500), Math.min(text.length, idx + 700)]); from = idx + t.length; n++; }
  }
  spans.sort((a, b) => a[0] - b[0]);
  const merged = [];
  for (const s of spans) { const l = merged[merged.length - 1]; if (l && s[0] <= l[1]) l[1] = Math.max(l[1], s[1]); else merged.push([...s]); }
  const body = merged.map(([a, b]) => text.slice(a, b)).join('\n[…]\n');
  return (text.slice(0, 600) + (body ? '\n[…]\n' + body : '')).slice(0, 5000);
};
const out = changes.map(c => {
  const terms = [...new Set([...(c.keywords_es || []), ...(c.keywords_en || []), ...String(c.statement).split(/[^\p{L}\p{N}]+/u).filter(w => w.length >= 5)])].map(t => t.toLowerCase()).slice(0, 20);
  const arts = Object.values(byChange[c.id] || {}).slice(0, 6).map(a => {
    const text = strip(a.body);
    return { article_id: a.id, locale: a.locale, title: a.title, url: a.html_url, updated_at: a.updated_at, passages: passages(text, terms) };
  });
  return { ...c, articles: arts };
});
return [{ json: { changes: out } }];

