// Joins Help Center findings + Aura staleness, removes what was already reported, builds Slack text and sheet rows.
const cfg = $('Config').first().json;
const digest = $('Build Digest').first().json;
const sd = $getWorkflowStaticData('global');
const now = Date.now();
const ran = (n) => { try { return $(n).isExecuted; } catch (e) { return false; } };

const changes = ran('Nova · Extract Changes') ? (($('Nova · Extract Changes').first().json.output || {}).changes || []) : [];
let findings = ran('Nova · Compare with Help Center') ? (($('Nova · Compare with Help Center').first().json.output || {}).findings || []) : [];
const chById = Object.fromEntries(changes.map(c => [c.id, c]));

// --- Aura copy older than the Help Center article (same article id + locale)
const auraPages = $('Get Aura Chunks').all().map(i => i.json);
const auraError = auraPages.some(p => p.error) || !auraPages.some(p => Array.isArray(p.data));
const aura = {};
for (const p of auraPages) for (const a of (p.data || [])) {
  const md = a.metadata || {};
  const id = String(md.source_article_id || ''), loc = String(md.source_locale || a.locale || '').toLowerCase();
  if (!id || a.enabled === false) continue;
  const t = Date.parse(a.external_updated || md.source_updated_at || 0) || 0;
  const k = id + '|' + loc;
  if (!aura[k] || t < aura[k].t) aura[k] = { t, title: md.source_title || a.name };
}
const stale = [];
for (const loc of cfg.locales) {
  const page = $('Zendesk · Recent Articles ' + loc).first();
  for (const a of ((page && page.json.articles) || [])) {
    const k = a.id + '|' + loc.toLowerCase();
    if (!aura[k] || a.draft) continue;
    const hc = Date.parse(a.edited_at || a.updated_at);
    if (hc - aura[k].t > 6 * 3600e3) stale.push({ article_id: String(a.id), locale: loc, title: a.title, url: a.html_url, hc_updated: (a.edited_at || a.updated_at).slice(0, 10), aura_updated: new Date(aura[k].t).toISOString().slice(0, 10) });
  }
}

// --- De-duplicate against previous runs (static data persists only on production runs)
sd.seen = Object.fromEntries(Object.entries(sd.seen || {}).filter(([, t]) => now - t < cfg.dedupe_days * 86400e3));
const norm = (s) => String(s || '').toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').trim().slice(0, 60);
const fKey = (f) => ['hc', f.status, f.article_id, f.locale, norm(f.change)].join('|');
const sKey = (s) => ['aura', s.article_id, s.locale, s.hc_updated].join('|');
const newFindings = findings.filter(f => !sd.seen[fKey(f)]);
const newStale = stale.filter(s => !sd.seen[sKey(s)]);
newFindings.forEach(f => sd.seen[fKey(f)] = now);
newStale.forEach(s => sd.seen[sKey(s)] = now);
sd.lastRun = digest.until;

// --- Slack text
const z = 'America/Bogota';
const fmt = (iso) => DateTime.fromISO(iso).setZone(z).setLocale('es').toFormat('d LLL HH:mm');
const sev = { high: '🔴', medium: '🟠', low: '🟡' };
const st = { contradicts: 'contradice', incomplete: 'incompleto', no_article: 'sin artículo' };
const lines = [`*Nova · Help Center vs Slack* · ${fmt(digest.since)} – ${fmt(digest.until)}`,
  `${digest.messages} mensajes en ${digest.channels_with_activity} canales · ${changes.length} cambios detectados · ${newFindings.length} diferencias nuevas en el Help Center · ${newStale.length} artículos con copia vieja en Aura`];
const sorted = newFindings.slice().sort((a, b) => ['high', 'medium', 'low'].indexOf(a.severity) - ['high', 'medium', 'low'].indexOf(b.severity));
for (const owner of ['B2C', 'B2B']) {
  const fs = sorted.filter(f => f.owner === owner);
  if (!fs.length) continue;
  lines.push(`\n*${owner} · ${cfg.owners[owner]}*`);
  for (const f of fs.slice(0, 10)) {
    const src = chById[f.change_id] && chById[f.change_id].source_link;
    const art = f.status === 'no_article' ? '_No hay artículo que lo cubra_' : `<${f.article_url}|${f.article_title}> (${f.locale})`;
    lines.push(`${sev[f.severity] || '•'} ${art} · *${st[f.status]}*\n   Slack${src ? ` (<${src}|mensaje>)` : ''}: ${f.change}` +
      (f.article_says ? `\n   Artículo: “${f.article_says}”` : '') + `\n   Ajuste: ${f.suggested_fix}`);
  }
  if (fs.length > 10) lines.push(`_…y ${fs.length - 10} más en la hoja._`);
}
if (newStale.length) {
  lines.push(`\n*Aura tiene una copia más vieja que el Help Center* (recargar chunks de la fuente Aura KB)`);
  newStale.slice(0, 12).forEach(s => lines.push(`• <${s.url}|${s.title}> (${s.locale}) · Help Center ${s.hc_updated} · Aura ${s.aura_updated}`));
  if (newStale.length > 12) lines.push(`_…y ${newStale.length - 12} más en la hoja._`);
}
if (!newFindings.length && !newStale.length) lines.push('\nSin diferencias nuevas. ✅');
const notes = [];
if (digest.slack_errors.length) notes.push('no pude leer: ' + digest.slack_errors.join(', '));
if (digest.digest_cut) notes.push('había demasiados mensajes y solo se revisaron los más recientes');
if (auraError) notes.push('no pude leer el knowledge de Aura (revisa la credencial de Ada en Get Aura Chunks)');
if (notes.length) lines.push(`\n_Nota: ${notes.join('; ')}._`);
lines.push('\n_Revisa y reenvía a Product Marketing lo que aplique. Nova no cambia nada en Zendesk ni en Aura._');

const runAt = digest.until;
const rows = newFindings.map(f => ({ run_at: runAt, type: 'help_center', status: f.status, severity: f.severity, owner: f.owner, owner_name: cfg.owners[f.owner],
  article_id: f.article_id, locale: f.locale, article_title: f.article_title, article_url: f.article_url, change: f.change, article_says: f.article_says,
  suggested_fix: f.suggested_fix, why: f.why, slack_source: (chById[f.change_id] || {}).source_link || '', hc_updated: '', aura_updated: '', follow_up: 'pendiente' }))
  .concat(newStale.map(s => ({ run_at: runAt, type: 'aura_stale', status: 'aura_outdated', severity: 'medium', owner: 'CX', owner_name: 'Mike',
  article_id: s.article_id, locale: s.locale, article_title: s.title, article_url: s.url, change: '', article_says: '', suggested_fix: 'Recargar los chunks de este artículo en Aura KB (Zendesk chunks)',
  why: 'El artículo se editó en Zendesk después de la última carga en Aura', slack_source: '', hc_updated: s.hc_updated, aura_updated: s.aura_updated, follow_up: 'pendiente' })));
return [{ json: { channel: cfg.review_channel, text: lines.join('\n'), rows } }];
